node -e 'const fs=require("fs")
const fail=(m)=>{console.error(m);process.exit(1)}
const V="components/spaces/space-profile-menu-view.tsx"
const src=fs.readFileSync(V,"utf8")
const code=src.replace(/\/\*[\s\S]*?\*\//g," ").replace(/\{\/\*[\s\S]*?\*\/\}/g," ").replace(/^\s*\/\/.*$/gm," ")
if(/<details[\s>]/.test(code))fail("the Space menu folds tabs behind a details popup again, the More menu the owner asked to remove")
const r=code.indexOf("data-space-menu-rail")
if(r<0)fail("the Space menu has no scroll rail")
const open=code.lastIndexOf("<div",r)
const cls=code.slice(r,code.indexOf(">",r))
if(!/overflow-x-auto/.test(cls)||!/min-w-0/.test(cls))fail("the rail is not a shrinkable horizontal scroller, so the tabs cannot scroll")
const m=code.indexOf("tabs.map(",r)
const close=code.indexOf("</div>",m)
if(m<0||close<0)fail("the rail does not render the tab list")
const manage=code.indexOf("panel=manage")
if(manage<0)fail("the Manage entry is gone")
if(manage<close)fail("Manage renders inside the scrolling rail, so it scrolls away with the tabs instead of staying pinned")
const pin=code.slice(close,manage)
if(!/shrink-0/.test(pin))fail("the Manage pin can be squeezed by the rail")
if(/use client/.test(src.slice(0,40)))fail("the view became a client component, which costs the prerendered share URL its menu (LIVE-522)")
console.log("LIVE-744 ok")'
